const webhookData = $('Webhook').item.json.body;

const originWeatherItem = $('Get Origin Weather').item.json;
const destWeatherItem = $('Get Destination Weather').item.json;
const routeItem = $('Get Route').item.json;

function summariseWeather(forecastJson, locationName) {
  try {
    const list = forecastJson.list || [];
    if (!list.length) return locationName + ': Weather data unavailable';
    const temps = list.map(e => e.main && e.main.temp).filter(t => t !== undefined);
    const tempMin = Math.round(Math.min(...temps));
    const tempMax = Math.round(Math.max(...temps));
    const rainProb = Math.round((list.reduce((sum, e) => sum + (e.pop || 0), 0) / list.length) * 100);
    const condition = (list[0].weather && list[0].weather[0] && list[0].weather[0].description) || 'unknown';
    return locationName + ': ' + tempMin + '°C – ' + tempMax + '°C, Rain probability: ' + rainProb + '%, Condition: ' + condition;
  } catch (err) {
    return locationName + ': Weather data parse error - ' + err.message;
  }
}

function extractStops(routeJson) {
  const stops = [];
  try {
    const features = routeJson.features || [];
    if (!features.length) return stops;
    const geometry = features[0].geometry;
    if (!geometry || geometry.type !== 'LineString') return stops;
    const coords = geometry.coordinates;
    if (!coords || coords.length < 4) return stops;
    const totalPoints = coords.length;
    let totalDistanceM = 0;
    try { totalDistanceM = features[0].properties.summary.distance || 0; } catch (_) {}
    [0.25, 0.50, 0.75].forEach(function(frac, idx) {
      const ptIdx = Math.floor(frac * (totalPoints - 1));
      const lon = coords[ptIdx][0];
      const lat = coords[ptIdx][1];
      const approxDistKm = totalDistanceM > 0 ? Math.round((frac * totalDistanceM) / 1000) : Math.round(frac * 100);
      stops.push({ stopNum: idx + 1, lat: lat.toFixed(4), lon: lon.toFixed(4), distanceKm: approxDistKm });
    });
  } catch (err) {}
  return stops;
}

const originWeatherSummary = summariseWeather(originWeatherItem, webhookData.origin);
const destWeatherSummary = summariseWeather(destWeatherItem, webhookData.destination);
const stops = extractStops(routeItem);

let stopsText = '';
if (stops.length) {
  stopsText = stops.map(s => 'Stop ' + s.stopNum + ': ~' + s.lat + ',' + s.lon + ' (approx ' + s.distanceKm + 'km from start)').join('\n');
} else {
  stopsText = 'Route stop data unavailable.';
}

const userMessage = 'TRIP PARAMETERS:\nOrigin: ' + webhookData.origin + '\nDestination: ' + webhookData.destination + '\nDates: ' + webhookData.dates + '\nBudget: ' + webhookData.budget + '\nTransport: ' + webhookData.transport + '\nStyle: ' + webhookData.style + '\n\nWEATHER DATA:\n' + originWeatherSummary + '\n' + destWeatherSummary + '\n\nROUTE STOPS (intermediate cities approx every 100km):\n' + stopsText;

return [{ json: { userMessage: userMessage } }];

const groqResponse = items[0].json;
let blueprint = '';
try {
  blueprint = groqResponse.choices[0].message.content;
} catch (err) {
  blueprint = 'Error extracting blueprint: ' + JSON.stringify(groqResponse).substring(0, 500);
}
return [{ json: { blueprint: blueprint } }];
